        possible_T = []
        for t, color in observations:
            if color == 'green':
                start = t % (Tg + Ty + Tr)
                if start < Tg:
                    possible_T.append((start, start + Tg))
            elif color == 'yellow':
                start = t % (Tg + Ty + Tr)
                if Tg <= start < Tg + Ty:
                    possible_T.append((start - Tg, start - Tg + Ty))
            elif color == 'red':
                start = t % (Tg + Ty + Tr)
                if Tg + Ty <= start < Tg + Ty + Tr:
                    possible_T.append((start - Tg - Ty, start - Tg - Ty + Tr))
        return possible_T

    def intersection(intervals):
        if not intervals:
            return []
        intervals.sort(key=lambda x: x[0])
        merged = [intervals[0]]
        for current in intervals[1:]:
            last_merged = merged[-1]
            if current[0] <= last_merged[1]:
                merged[-1] = (last_merged[0], max(last_merged[1], current[1]))
            else:
                merged.append(current)
        return merged

    def calculate_probability(Tg, Ty, Tr, possible_T, tq, cq):
        total_length = Tg + Ty + Tr
        valid_length = 0
        for start, end in possible_T:
            if cq == 'green':
